 $scope=!$canReview?" AND (p.created_by=? OR (p.status='published' AND EXISTS(SELECT 1 FROM teacher_assignments a WHERE a.user_id=? AND a.school_id=p.school_id AND a.active=1 AND a.class_level=c.name AND a.subject=s.name)))":'';$params=[$school];if(!$canReview)array_push($params,$uid,$uid);$q=$db->prepare("SELECT p.id,p.title,p.holiday_period,p.available_from,p.available_until,p.status,p.created_by,p.review_feedback,p.updated_at,c.name class_name,s.name subject_name,u.name author_name,(SELECT COUNT(*) FROM holiday_package_items i WHERE i.package_id=p.id) item_count,(SELECT COUNT(*) FROM holiday_package_progress pr WHERE pr.package_id=p.id AND pr.status='completed') completed_count,((SELECT COUNT(*) FROM holiday_package_progress pr WHERE pr.package_id=p.id)+(SELECT COUNT(*) FROM pupils p2 WHERE p2.school_id=p.school_id AND p2.class_level=c.name AND p2.status='active' AND NOT EXISTS(SELECT 1 FROM holiday_package_progress pr2 WHERE pr2.package_id=p.id AND pr2.pupil_id=p2.id))) assigned_count FROM holiday_packages p JOIN school_classes c ON c.id=p.class_id JOIN school_class_subjects s ON s.id=p.subject_id JOIN users u ON u.id=p.created_by WHERE p.school_id=?$scope ORDER BY p.updated_at DESC LIMIT 200");$q->execute($params);hp_ok('Packages loaded.',['packages'=>$q->fetchAll(),'can_review'=>$canReview,'role'=>$role]);
