eption('Choose a published learning note for this class and subject.');}if($questionId){$q=$db->prepare("SELECT id FROM question_bank WHERE id=? AND school_id=? AND class_id=? AND subject_id=? AND status='published'");$q->execute([$questionId,$school,$package['class_id'],$package['subject_id']]);if(!$q->fetchColumn())throw new DomainException('Choose a published question for this class and subject.');}if($itemId){$q=$db->prepare('UPDATE holiday_package_items SET sequence_no=?,item_type=?,title=?,instructions=?,content=?,learning_note_id=?,question_id=? WHERE id=? AND package_id=? AND school_id=?');$q->execute([$sequence,$type,$title,$instructions?:null,$content?:null,$noteId?:null,$questionId?:null,$itemId,$packageId,$school]);$exists=$db->prepare('SELECT 1 FROM holiday_package_items WHERE id=? AND package_id=? AND school_id=?');$exists->execute([$itemId,$packageId,$school]);if(!$exists->fetchColumn())throw new DomainException('That package item could not be updated.');}else{$q=$db->prepare('INSERT INTO holiday_package_items(package_id,school_id,sequence_no,item_type,title,instructions,content,learning_note_id,question_id) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$packageId,$school,$sequence,$type,$title,$instructions?:null,$content?:null,$noteId?:null,$questionId?:null]);$itemId=(int)$db->lastInsertId();}hp_audit($db,$uid,'save_item',$packageId,['school_id'=>$school,'item_id'=>$itemId,'item_type'=>$type]);$db->commit();hp_ok('Package item saved.',['package_id'=>$packageId]);
